args.sparql:
SELECT ?director ?directorLabel ?birthplace ?birthplaceLabel WHERE {
  dbr:Doctor_Krishna dbo:director ?director .
  OPTIONAL { ?director dbo:birthPlace ?birthplace . }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }
  OPTIONAL { ?birthplace rdfs:label ?birthplaceLabel FILTER (lang(?birthplaceLabel) = "en") }
}

output.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?director ?directorLabel ?birthplace ?birthplaceLabel WHERE {
  dbr:Doctor_Krishna dbo:director ?director .
  OPTIONAL {
    ?director dbo:birthPlace ?birthplace .
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(lang(?directorLabel) = "en")
  }
  OPTIONAL {
    ?birthplace rdfs:label ?birthplaceLabel
    FILTER(lang(?birthplaceLabel) = "en")
  }
}

